import { getAddress, isAddress, keccak256, toBytes, type Hex } from 'viem';
import {
  FACILITATOR_SELLER_PROOF_DOMAIN_NAME,
  FACILITATOR_SELLER_PROOF_DOMAIN_VERSION,
  FACILITATOR_SELLER_PROOF_MAX_CLOCK_SKEW_SECONDS,
  FACILITATOR_SELLER_PROOF_MAX_TTL_SECONDS,
  FACILITATOR_SELLER_PROOF_TTL_SECONDS,
  FACILITATOR_SELLER_PROOF_VERSION,
} from '../constants';
import { createNonce } from '../nonce';
import type { EvmSigner } from '../types';

/**
 * Route class a seller proof authorizes. Must match the endpoint it is sent to.
 */
export type SellerProofPurpose = 'verify' | 'settle' | 'status' | 'claim';

const PURPOSES: ReadonlySet<string> = new Set(['verify', 'settle', 'status', 'claim']);
const HEX = /^0x[0-9a-fA-F]*$/;
const BYTES32 = /^0x[0-9a-fA-F]{64}$/;

/**
 * The request a seller proof is bound to. `body` must be the exact bytes sent
 * on the wire; a bodyless request (GET) hashes empty bytes.
 */
export interface SellerProofRequest {
  purpose: SellerProofPurpose;
  method: string;
  body?: string | Uint8Array;
  /** CAIP-2 network of the payment, e.g. `eip155:5042002`. */
  network: string;
  /** Seller destination address being proven. */
  payTo: string;
}

export interface SellerProofOptions {
  /** 32-byte hex nonce, unique per (network, payTo). Random when omitted. */
  nonce?: Hex;
  /** Unix seconds. Defaults to now. */
  issuedAt?: number;
  /** Proof lifetime in seconds; at most `FACILITATOR_SELLER_PROOF_MAX_TTL_SECONDS`. */
  ttlSeconds?: number;
}

/**
 * Decoded `Facilitator-Seller-Proof` header.
 */
export interface SellerProofHeader {
  version: typeof FACILITATOR_SELLER_PROOF_VERSION;
  signature: Hex;
  network: string;
  payTo: string;
  nonce: Hex;
  issuedAt: number;
  expiresAt: number;
}

export type SellerProofFields = Omit<SellerProofHeader, 'version' | 'signature'>;

/**
 * EIP-712 struct signed by the seller.
 */
export const SELLER_REQUEST_TYPES = {
  SellerRequest: [
    { name: 'purpose', type: 'string' },
    { name: 'method', type: 'string' },
    { name: 'bodyHash', type: 'bytes32' },
    { name: 'network', type: 'string' },
    { name: 'payTo', type: 'address' },
    { name: 'nonce', type: 'bytes32' },
    { name: 'issuedAt', type: 'uint64' },
    { name: 'expiresAt', type: 'uint64' },
  ],
} as const;

/**
 * keccak256 of the raw request body. Strings are hashed as UTF-8; an absent
 * body hashes empty bytes.
 */
export function hashSellerProofBody(body?: string | Uint8Array): Hex {
  if (body === undefined) {
    return keccak256(new Uint8Array());
  }
  return keccak256(typeof body === 'string' ? toBytes(body) : body);
}

/**
 * Parse the numeric chain id out of a canonical `eip155:<chainId>` network.
 */
export function chainIdFromNetwork(network: string): number {
  const match = /^eip155:([1-9][0-9]*)$/.exec(network);
  if (!match) {
    throw new Error(
      `Seller proof: unsupported network "${network}". Expected "eip155:<chainId>"`,
    );
  }
  return Number(match[1]);
}

/**
 * Build the EIP-712 typed data for a seller proof. Exposed so callers can
 * verify or inspect what will be signed.
 */
export function buildSellerProofTypedData(
  request: SellerProofRequest,
  fields: SellerProofFields,
) {
  return {
    domain: {
      name: FACILITATOR_SELLER_PROOF_DOMAIN_NAME,
      version: FACILITATOR_SELLER_PROOF_DOMAIN_VERSION,
      chainId: chainIdFromNetwork(fields.network),
    },
    types: SELLER_REQUEST_TYPES,
    primaryType: 'SellerRequest' as const,
    message: {
      purpose: request.purpose,
      method: request.method.toUpperCase(),
      bodyHash: hashSellerProofBody(request.body),
      network: fields.network,
      payTo: getAddress(fields.payTo),
      nonce: fields.nonce,
      issuedAt: BigInt(fields.issuedAt),
      expiresAt: BigInt(fields.expiresAt),
    },
  };
}

/**
 * Sign a seller proof for one request and return the
 * `Facilitator-Seller-Proof` header value (base64url JSON).
 */
export async function createSellerProof(
  signer: EvmSigner,
  request: SellerProofRequest,
  options: SellerProofOptions = {},
): Promise<string> {
  if (!PURPOSES.has(request.purpose)) {
    throw new Error(`Seller proof: unsupported purpose "${request.purpose}"`);
  }
  if (!request.method) {
    throw new Error('Seller proof: method is required');
  }
  if (!isAddress(request.payTo)) {
    throw new Error(`Seller proof: invalid payTo address "${request.payTo}"`);
  }
  const ttlSeconds = options.ttlSeconds ?? FACILITATOR_SELLER_PROOF_TTL_SECONDS;
  if (
    !Number.isInteger(ttlSeconds) ||
    ttlSeconds <= 0 ||
    ttlSeconds > FACILITATOR_SELLER_PROOF_MAX_TTL_SECONDS
  ) {
    throw new Error(
      `Seller proof: ttlSeconds must be an integer between 1 and ${FACILITATOR_SELLER_PROOF_MAX_TTL_SECONDS}`,
    );
  }

  if (options.nonce !== undefined && !BYTES32.test(options.nonce)) {
    throw new Error('Seller proof: nonce must be 32 bytes of hex');
  }
  const now = Math.floor(Date.now() / 1000);
  const issuedAt = options.issuedAt ?? now;
  if (
    !Number.isInteger(issuedAt) ||
    issuedAt < 0 ||
    issuedAt > now + FACILITATOR_SELLER_PROOF_MAX_CLOCK_SKEW_SECONDS
  ) {
    throw new Error(
      `Seller proof: issuedAt must be unix seconds no more than ${FACILITATOR_SELLER_PROOF_MAX_CLOCK_SKEW_SECONDS}s in the future`,
    );
  }

  const fields: SellerProofFields = {
    network: request.network,
    payTo: getAddress(request.payTo),
    nonce: options.nonce ?? createNonce(),
    issuedAt,
    expiresAt: issuedAt + ttlSeconds,
  };

  const typedData = buildSellerProofTypedData(request, fields);
  const signature = await signer.signTypedData({
    ...typedData,
    types: SELLER_REQUEST_TYPES as unknown as Record<
      string,
      Array<{ name: string; type: string }>
    >,
  });

  return encodeSellerProof({
    version: FACILITATOR_SELLER_PROOF_VERSION,
    signature,
    ...fields,
  });
}

/**
 * Encode a seller proof header as unpadded base64url JSON.
 */
export function encodeSellerProof(header: SellerProofHeader): string {
  return Buffer.from(JSON.stringify(header), 'utf-8').toString('base64url');
}

/**
 * Decode a `Facilitator-Seller-Proof` header value. Accepts padded or
 * unpadded base64url.
 */
export function decodeSellerProof(value: string): SellerProofHeader {
  let parsed: unknown;
  try {
    parsed = JSON.parse(
      Buffer.from(value.replace(/=+$/, ''), 'base64url').toString('utf-8'),
    );
  } catch {
    throw new Error('Seller proof: header is not base64url JSON');
  }
  if (
    typeof parsed !== 'object' ||
    parsed === null ||
    (parsed as { version?: unknown }).version !== FACILITATOR_SELLER_PROOF_VERSION
  ) {
    throw new Error('Seller proof: unsupported header version');
  }
  const header = parsed as Record<string, unknown>;
  const wellFormed =
    typeof header.signature === 'string' &&
    HEX.test(header.signature) &&
    typeof header.network === 'string' &&
    typeof header.payTo === 'string' &&
    isAddress(header.payTo) &&
    typeof header.nonce === 'string' &&
    BYTES32.test(header.nonce) &&
    Number.isInteger(header.issuedAt) &&
    Number.isInteger(header.expiresAt);
  if (!wellFormed) {
    throw new Error('Seller proof: malformed header');
  }
  return parsed as SellerProofHeader;
}
