import type { EvmSigner } from '../types';
import { CIRCLE_BATCHING_SCHEME, FACILITATOR_MAX_TIMEOUT_SECONDS } from '../constants';
import { isToken } from '../config';
import {
  CircleFacilitatorClient,
  type FacilitatorPaymentStatus,
  type FacilitatorSupportedKind,
} from './CircleFacilitatorClient';
import {
  createPaymentMiddleware,
  parsePrice,
  type PaymentMiddlewareCore,
  type PaymentMiddlewareHooks,
} from './middleware';

/**
 * Configuration for the Circle Facilitator middleware.
 */
export interface FacilitatorMiddlewareConfig {
  /**
   * Seller's wallet address to receive payments. Defaults to
   * `sellerSigner.address`; required when authenticating with `apiKey` only.
   */
  sellerAddress?: string;
  /**
   * Keyless authentication: signs a seller proof for every Facilitator request.
   * Must control `sellerAddress` (an EOA key, or a signer the ERC-1271
   * contract at `sellerAddress` accepts).
   */
  sellerSigner?: EvmSigner;
  /** Registered authentication: Circle API key sent as a Bearer token. */
  apiKey?: string;
  /**
   * Networks to accept payments on.
   * - If omitted, accepts payments on ALL Facilitator-supported networks
   * - Can be a single network string or array of networks
   * - Format: CAIP-2 (e.g., 'eip155:8453' for Base, 'eip155:5042' for Arc)
   */
  networks?: string | string[];
  /** Facilitator base URL. Defaults to `FACILITATOR_URL`. */
  facilitatorUrl?: string;
  /** Additional headers merged into every outbound Facilitator request. */
  headers?: Record<string, string>;
  /** Optional resource description */
  description?: string;
  /**
   * Authorization lifetime advertised to buyers (`validBefore = now + this`).
   * Defaults to `FACILITATOR_MAX_TIMEOUT_SECONDS`.
   */
  maxTimeoutSeconds?: number;
  /** Seller proof lifetime in seconds (keyless only). */
  proofTtlSeconds?: number;
  /**
   * Call `/verify` before `/settle` (default `false`). The Facilitator's
   * settle repeats every check, so verify only adds latency. Verify hooks
   * never run while this is `false`.
   */
  verifyBeforeSettle?: boolean;
}

/**
 * Circle Facilitator middleware instance. Same negotiation surface and
 * lifecycle hooks as {@link GatewayMiddleware}, plus payment status lookup.
 */
export interface FacilitatorMiddleware
  extends PaymentMiddlewareCore, PaymentMiddlewareHooks<FacilitatorMiddleware> {
  /** The underlying client, for direct verify/settle/status/claim calls. */
  readonly facilitatorClient: CircleFacilitatorClient;
  /**
   * Look up a payment that settled as `settlement_pending`. Keyless sellers
   * must pass the payment's network.
   */
  getStatus: (
    paymentId: string,
    options?: { network?: string },
  ) => Promise<FacilitatorPaymentStatus>;
}

/**
 * Create Express middleware that charges for routes through the Circle
 * Facilitator (hosted on-chain USDC settlement, no buyer deposit required).
 *
 * Buyers pay with a standard x402 `exact` EIP-3009 authorization signed under
 * the USDC token's own EIP-712 domain, so any stock x402 client works.
 *
 * A settlement whose outcome is still unknown after the Facilitator's wait
 * returns `402` with `reason: "settlement_pending"` and a `settlementStatus`
 * carrying the `paymentId`; the protected handler does not run. Use
 * `getStatus` to reconcile.
 *
 * @example
 * ```typescript
 * import express from 'express';
 * import { privateKeyToAccount } from 'viem/accounts';
 * import { createFacilitatorMiddleware } from '@circle-fin/x402-batching/server';
 *
 * const app = express();
 *
 * // Keyless: prove control of the seller address on every request
 * const facilitator = createFacilitatorMiddleware({
 *   sellerSigner: privateKeyToAccount(process.env.SELLER_PRIVATE_KEY as `0x${string}`),
 *   networks: ['eip155:5042002'], // Arc Testnet
 * });
 *
 * app.get('/listing/42', facilitator.require('$0.25'), (req, res) => {
 *   res.json({ content: 'Paid content!' });
 * });
 * ```
 */
export function createFacilitatorMiddleware(
  config: FacilitatorMiddlewareConfig,
): FacilitatorMiddleware {
  if (!config.sellerSigner && !config.apiKey) {
    throw new Error(
      'createFacilitatorMiddleware: provide sellerSigner (keyless) or apiKey (registered)',
    );
  }
  const sellerAddress = config.sellerAddress ?? config.sellerSigner?.address;
  if (!sellerAddress) {
    throw new Error('createFacilitatorMiddleware: sellerAddress is required with apiKey');
  }

  const facilitatorClient = new CircleFacilitatorClient({
    url: config.facilitatorUrl,
    apiKey: config.apiKey,
    sellerSigner: config.sellerSigner,
    sellerAddress,
    headers: config.headers,
    proofTtlSeconds: config.proofTtlSeconds,
  });
  const maxTimeoutSeconds = config.maxTimeoutSeconds ?? FACILITATOR_MAX_TIMEOUT_SECONDS;

  const api = createPaymentMiddleware<FacilitatorSupportedKind>({
    component: 'FacilitatorMiddleware',
    facilitator: facilitatorClient,
    networks: config.networks,
    description: config.description,
    verifyBeforeSettle: config.verifyBeforeSettle ?? false,
    buildRequirements: (kinds, { token, price }) =>
      kinds
        .filter(
          (kind) =>
            kind.scheme === CIRCLE_BATCHING_SCHEME &&
            kind.asset &&
            isToken(kind, token) &&
            kind.extra?.name &&
            kind.extra?.version,
        )
        .map((kind) => ({
          scheme: CIRCLE_BATCHING_SCHEME,
          network: kind.network,
          asset: kind.asset,
          amount: parsePrice(price, kind.decimals ?? 6),
          payTo: sellerAddress,
          maxTimeoutSeconds,
          extra: { name: kind.extra.name, version: kind.extra.version },
        })),
  });

  return Object.assign(api, {
    facilitatorClient,
    getStatus: (paymentId: string, options?: { network?: string }) =>
      facilitatorClient.getStatus(paymentId, options),
  }) as unknown as FacilitatorMiddleware;
}
