import type { CircleFacilitatorConfig } from '../types';
import {
  FACILITATOR_SELLER_PROOF_HEADER,
  FACILITATOR_SETTLEMENT_PENDING,
  FACILITATOR_URL,
} from '../constants';
import {
  BaseFacilitatorClient,
  type PaymentPayload,
  type PaymentRequirements,
  type SettleResponse,
  type SupportedKind,
  type SupportedResponse,
  type VerifyResponse,
} from './BaseFacilitatorClient';
import { createSellerProof, type SellerProofPurpose } from './sellerProof';

/**
 * One payment profile advertised by the Circle Facilitator: USDC on one
 * network, signed under the token's own EIP-712 domain (`extra.name` /
 * `extra.version`), settled on-chain via EIP-3009.
 */
export interface FacilitatorSupportedKind extends SupportedKind {
  asset: string;
  decimals: number;
  extra: { name: string; version: string };
}

export interface FacilitatorSupportedResponse extends SupportedResponse {
  x402Version: number;
  kinds: FacilitatorSupportedKind[];
}

/**
 * Closed public status set of a Circle Facilitator payment.
 */
export type FacilitatorPaymentStatusValue = 'pending' | 'completed' | 'failed';

/**
 * `settlement-status` extension returned on unresolved or failed settlements.
 * `paymentId` is the reconcile handle for `getStatus`.
 */
export interface FacilitatorSettlementStatus {
  status: FacilitatorPaymentStatusValue;
  paymentId: string;
  statusUrl: string;
}

export interface FacilitatorSettleResponse extends SettleResponse {
  /** Settled amount in base units; present on terminal success. */
  amount?: string;
  extensions?: { 'settlement-status'?: FacilitatorSettlementStatus };
}

/**
 * `GET /status/{paymentId}` body.
 */
export interface FacilitatorPaymentStatus {
  paymentId: string;
  status: FacilitatorPaymentStatusValue;
  reason: string | null;
  transaction: string | null;
  network: string;
  amount: string;
  payer: string | null;
  nextAction: string | null;
  retryAfterMs: number | null;
  expiresAt: string | null;
  updatedAt: string;
}

export interface SellerAccountClaimResponse {
  status: string;
  payTo: string;
  entityId: string;
}

/**
 * Non-2xx response from the Circle Facilitator. `reason` carries the
 * contractual error reason when the Facilitator supplied one (e.g.
 * `registration_required`, `payment_identifier_conflict`).
 */
export class FacilitatorApiError extends Error {
  readonly status: number;
  readonly code?: number;
  readonly reason?: string;
  readonly body: unknown;

  constructor(route: string, status: number, body: unknown) {
    const detail =
      typeof body === 'object' && body !== null && 'message' in body
        ? String((body as { message: unknown }).message)
        : typeof body === 'string'
          ? body
          : JSON.stringify(body);
    super(`Circle Facilitator ${route} failed (${status}): ${detail}`);
    this.name = 'FacilitatorApiError';
    this.status = status;
    this.body = body;
    if (typeof body === 'object' && body !== null) {
      const { code, errors } = body as {
        code?: unknown;
        errors?: Array<{ reason?: unknown }>;
      };
      if (typeof code === 'number') this.code = code;
      const reason = errors?.[0]?.reason;
      if (typeof reason === 'string') this.reason = reason;
    }
  }
}

/**
 * True when the Facilitator accepted the payment but did not observe its
 * on-chain outcome within the settlement wait. The payment is neither paid
 * nor failed yet: do not deliver, and reconcile with `getStatus`.
 */
export function isSettlementPending(result: SettleResponse): boolean {
  return !result.success && result.errorReason === FACILITATOR_SETTLEMENT_PENDING;
}

/**
 * Circle Facilitator client.
 *
 * A `FacilitatorClient` for Circle's hosted x402 facilitator, which settles
 * `exact` USDC payments on-chain through EIP-3009 (no Gateway deposit needed
 * by the buyer). Plugs into `x402ResourceServer` like any facilitator client
 * and adds `getStatus` / `claimSellerAccount` for the Facilitator's seller
 * account model.
 *
 * Settlement is synchronous: an accepted `/settle` answers 200 and `success`
 * carries the verdict; a 4xx/5xx throws {@link FacilitatorApiError}. A payment
 * whose outcome is still unknown after the wait comes back as `success: false, errorReason: "settlement_pending"` with a
 * `paymentId` in `extensions["settlement-status"]` — see {@link isSettlementPending}.
 *
 * @example
 * ```typescript
 * import { privateKeyToAccount } from 'viem/accounts';
 * import { CircleFacilitatorClient } from '@circle-fin/x402-batching/server';
 *
 * // Keyless: prove control of the seller address on every request
 * const facilitator = new CircleFacilitatorClient({
 *   sellerSigner: privateKeyToAccount(process.env.SELLER_PRIVATE_KEY),
 * });
 *
 * // Registered: authenticate with a Circle API key instead
 * const registered = new CircleFacilitatorClient({ apiKey: process.env.CIRCLE_API_KEY });
 * ```
 */
export class CircleFacilitatorClient extends BaseFacilitatorClient<
  VerifyResponse,
  FacilitatorSettleResponse,
  FacilitatorSupportedResponse
> {
  protected readonly component = 'CircleFacilitatorClient';

  readonly url: string;
  readonly sellerAddress?: string;
  private readonly _apiKey?: string;
  private readonly _signer?: CircleFacilitatorConfig['sellerSigner'];
  private readonly _headers: Record<string, string>;
  private readonly _proofTtlSeconds?: number;

  constructor(config: CircleFacilitatorConfig = {}) {
    super();
    this.url = (config.url ?? FACILITATOR_URL).replace(/\/$/, '');
    this._apiKey = config.apiKey;
    this._signer = config.sellerSigner;
    this.sellerAddress = config.sellerAddress ?? config.sellerSigner?.address;
    this._headers = config.headers ?? {};
    this._proofTtlSeconds = config.proofTtlSeconds;
  }

  protected callVerify(
    paymentPayload: PaymentPayload,
    paymentRequirements: PaymentRequirements,
  ): Promise<VerifyResponse> {
    return this.postPayment('verify', paymentPayload, paymentRequirements, 'isValid');
  }

  protected callSettle(
    paymentPayload: PaymentPayload,
    paymentRequirements: PaymentRequirements,
  ): Promise<FacilitatorSettleResponse> {
    return this.postPayment('settle', paymentPayload, paymentRequirements, 'success');
  }

  /**
   * Advertised payment profiles. Public, no authentication.
   */
  async getSupported(): Promise<FacilitatorSupportedResponse> {
    const response = await fetch(`${this.url}/supported`, {
      method: 'GET',
      headers: this.baseHeaders(),
    });
    return this.parse<FacilitatorSupportedResponse>(response, 'supported', (data) =>
      Array.isArray(data.kinds),
    );
  }

  /**
   * Seller-facing status of one payment. Keyless callers must pass the
   * payment's `network`, because the status proof binds `(network, payTo)`.
   */
  async getStatus(
    paymentId: string,
    options: { network?: string } = {},
  ): Promise<FacilitatorPaymentStatus> {
    const path = `/status/${encodeURIComponent(paymentId)}`;
    const headers = await this.authHeaders({
      purpose: 'status',
      method: 'GET',
      network: options.network,
    });
    const response = await fetch(`${this.url}${path}`, { method: 'GET', headers });
    return this.parse<FacilitatorPaymentStatus>(
      response,
      'status',
      (data) => typeof data.status === 'string',
    );
  }

  /**
   * Bind the keyless seller account for `(network, sellerAddress)` to the
   * entity that owns the configured API key. Requires both `apiKey` and
   * `sellerSigner`.
   */
  async claimSellerAccount(params: {
    entityId: string;
    network: string;
  }): Promise<SellerAccountClaimResponse> {
    if (!this._apiKey || !this._signer) {
      throw new Error(
        'CircleFacilitatorClient: claimSellerAccount requires both apiKey and sellerSigner',
      );
    }
    const body = JSON.stringify({ entityId: params.entityId });
    const headers = await this.authHeaders({
      purpose: 'claim',
      method: 'POST',
      body,
      network: params.network,
      both: true,
    });
    const response = await fetch(`${this.url}/seller-accounts/claim`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...headers },
      body,
    });
    return this.parse<SellerAccountClaimResponse>(
      response,
      'seller-accounts/claim',
      (data) => typeof data.status === 'string',
    );
  }

  private async postPayment<T extends VerifyResponse | FacilitatorSettleResponse>(
    route: 'verify' | 'settle',
    paymentPayload: PaymentPayload,
    paymentRequirements: PaymentRequirements,
    verdictField: 'isValid' | 'success',
  ): Promise<T> {
    // The seller proof signs these exact bytes, so serialize once and send that string.
    const body = JSON.stringify({
      x402Version: paymentPayload.x402Version ?? 2,
      paymentPayload: this.toJsonSafe(paymentPayload),
      paymentRequirements: this.toJsonSafe(paymentRequirements),
    });
    const headers = await this.authHeaders({
      purpose: route,
      method: 'POST',
      body,
      network: paymentRequirements.network,
      payTo: paymentRequirements.payTo,
    });

    const response = await fetch(`${this.url}/${route}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...headers },
      body,
    });

    return this.parse<T>(response, route, (data) => verdictField in data);
  }

  private async parse<T>(
    response: Response,
    route: string,
    isExpectedShape: (data: Record<string, unknown>) => boolean,
  ): Promise<T> {
    const text = await response.text();
    let data: unknown = text;
    if (text) {
      try {
        data = JSON.parse(text);
      } catch {
        data = text;
      }
    }
    if (
      response.ok &&
      typeof data === 'object' &&
      data !== null &&
      isExpectedShape(data as Record<string, unknown>)
    ) {
      return data as T;
    }
    throw new FacilitatorApiError(route, response.status, data);
  }

  private baseHeaders(): Record<string, string> {
    return { ...this._headers };
  }

  private async authHeaders(params: {
    purpose: SellerProofPurpose;
    method: string;
    body?: string;
    network?: string;
    payTo?: string;
    both?: boolean;
  }): Promise<Record<string, string>> {
    const headers = this.baseHeaders();
    const useApiKey = Boolean(this._apiKey);
    const useProof = Boolean(this._signer) && (params.both || !useApiKey);

    if (!useApiKey && !useProof) {
      throw new Error(
        `CircleFacilitatorClient: configure apiKey or sellerSigner to call /${params.purpose}`,
      );
    }
    if (useApiKey) {
      headers.Authorization = `Bearer ${this._apiKey}`;
    }
    if (useProof) {
      const payTo = params.payTo ?? this.sellerAddress;
      if (!params.network || !payTo) {
        throw new Error(
          `CircleFacilitatorClient: keyless /${params.purpose} needs the payment network and seller address`,
        );
      }
      headers[FACILITATOR_SELLER_PROOF_HEADER] = await createSellerProof(
        this._signer!,
        {
          purpose: params.purpose,
          method: params.method,
          body: params.body,
          network: params.network,
          payTo,
        },
        { ttlSeconds: this._proofTtlSeconds },
      );
    }
    return headers;
  }
}
