import { CIRCLE_BATCHING_VERSION, CIRCLE_BATCHING_VERSION_V2 } from '../constants';

/**
 * An asset that Gateway lists for a network.
 */
export interface GatewayAsset {
  address: string;
  symbol: string;
  decimals: number;
  /** Batching versions Gateway accepts for this asset. */
  authorizationVersions?: string[];
}

/**
 * Supported network kind from Circle Gateway.
 */
export interface GatewaySupportedKind {
  network: string;
  extra?: {
    version?: string;
    verifyingContract?: string;
    assets?: GatewayAsset[];
    [key: string]: unknown;
  };
}

/**
 * The batching versions that Gateway accepts for an asset of a kind, from the
 * lowest to the highest.
 */
export function acceptedBatchingVersions(
  kind: GatewaySupportedKind,
  asset: GatewayAsset,
): string[] {
  if (asset.authorizationVersions?.length) {
    return [...asset.authorizationVersions].sort((a, b) => Number(a) - Number(b));
  }

  return [minSupportedBatchingVersion(kind, asset)];
}

function minSupportedBatchingVersion(
  kind: GatewaySupportedKind,
  asset: GatewayAsset,
): string {
  // Gateway accepts version 1 for USDC only.
  const kindVersion = kind.extra?.version;
  const minVersion =
    asset.symbol === 'USDC' ? CIRCLE_BATCHING_VERSION : CIRCLE_BATCHING_VERSION_V2;
  return kindVersion && Number(kindVersion) >= Number(minVersion)
    ? kindVersion
    : minVersion;
}
