import type { IncomingMessage, ServerResponse } from 'http';
import { FACILITATOR_SETTLEMENT_PENDING } from '../constants';
import type { TokenName } from '../config';
import {
  warnHookFailure,
  type BeforeVerifyHook,
  type AfterVerifyHook,
  type OnVerifyFailureHook,
  type BeforeSettleHook,
  type AfterSettleHook,
  type OnSettleFailureHook,
  type OnVerifiedPaymentCanceledHook,
  type ProtectedRequestHook,
  type ProtectedRequestContext,
  type ProtectedRouteConfig,
  type VerifyContext,
  type VerifyResultContext,
  type VerifyFailureContext,
  type SettleContext,
  type SettleResultContext,
  type SettleFailureContext,
  type VerifiedPaymentCancellationReason,
  type VerifiedPaymentCanceledContext,
  type HookPaymentPayload,
  type HookVerifyResponse,
  type HookSettleResponse,
} from '../hooks';

// ============================================================================
// TYPES
// ============================================================================

/**
 * Payment requirements for 402 responses.
 */
export interface PaymentRequirements {
  scheme: string;
  network: string;
  asset: string;
  amount: string;
  payTo: string;
  maxTimeoutSeconds: number;
  extra: Record<string, unknown> & {
    name: string;
    version: string;
  };
}

/**
 * Express-compatible request with payment info.
 */
export interface PaymentRequest extends IncomingMessage {
  payment?: {
    /** Whether the payment was verified */
    verified: boolean;
    /** Payer's address */
    payer: string;
    /** Amount paid in smallest units */
    amount: string;
    /** Network the payment was made on */
    network: string;
    /** Token contract address of the payment */
    asset: string;
    /** Transaction hash after settlement */
    transaction?: string;
  };
  body?: unknown;
}

/**
 * Express-compatible response.
 */
export interface PaymentResponse extends ServerResponse {
  json?: (data: unknown) => void;
  status?: (code: number) => PaymentResponse;
}

/**
 * Express-compatible next function.
 */
export type NextFunction = (err?: unknown) => void;

/**
 * Express-compatible middleware function.
 */
export type MiddlewareFunction = (
  req: PaymentRequest,
  res: PaymentResponse,
  next: NextFunction,
) => void | Promise<void>;

// ============================================================================
// MIDDLEWARE FACTORY
// ============================================================================

/**
 * A price in the units of a token, for example
 * `{ token: 'EURC', price: '0.009' }`.
 */
export interface TokenPrice {
  token: TokenName;
  price: string;
}

/**
 * The price of a route. A string is a USDC price, for example `'$0.01'` or
 * `'0.01'`.
 */
export type RoutePrice = string | TokenPrice;

export interface PaymentMiddlewareCore {
  /** Returns middleware that requires a payment of `price`. */
  require: (price: RoutePrice) => MiddlewareFunction;

  verify: (
    payment: unknown,
  ) => Promise<{ valid: boolean; payer?: string; error?: string }>;

  settle: (payment: unknown) => Promise<{
    success: boolean;
    transaction?: string;
    error?: string;
    extensions?: Record<string, unknown>;
  }>;
}

/** Chainable lifecycle hook registration; see {@link GatewayMiddleware}. */
export interface PaymentMiddlewareHooks<Self> {
  onProtectedRequest: (hook: ProtectedRequestHook) => Self;
  onBeforeVerify: (hook: BeforeVerifyHook) => Self;
  onAfterVerify: (hook: AfterVerifyHook) => Self;
  onVerifyFailure: (hook: OnVerifyFailureHook) => Self;
  onBeforeSettle: (hook: BeforeSettleHook) => Self;
  onAfterSettle: (hook: AfterSettleHook) => Self;
  onSettleFailure: (hook: OnSettleFailureHook) => Self;
  onVerifiedPaymentCanceled: (hook: OnVerifiedPaymentCanceledHook) => Self;
}

interface GenericPaymentMiddleware
  extends PaymentMiddlewareCore, PaymentMiddlewareHooks<GenericPaymentMiddleware> {}

interface MiddlewareFacilitator<TKind> {
  verify(
    paymentPayload: HookPaymentPayload,
    requirements: PaymentRequirements,
  ): Promise<HookVerifyResponse>;
  settle(
    paymentPayload: HookPaymentPayload,
    requirements: PaymentRequirements,
  ): Promise<HookSettleResponse>;
  getSupported(): Promise<{ kinds: TKind[] }>;
}

/** Internal options shared by the public middleware factories. */
export interface PaymentMiddlewareOptions<TKind extends { network: string }> {
  component: string;
  facilitator: MiddlewareFacilitator<TKind>;
  networks?: string | string[];
  description?: string;
  /**
   * Turn the facilitator's accepted kinds into 402 payment requirements for
   * `price`. Kinds the builder cannot price are simply left out.
   */
  buildRequirements: (kinds: TKind[], price: TokenPrice) => PaymentRequirements[];
  /**
   * Whether a requirement from `buildRequirements` is the one that the buyer
   * accepted (default: the requirement is on the network that the buyer
   * accepted).
   */
  matchesAccepted?: (
    requirement: PaymentRequirements,
    accepted: PaymentRequirements,
  ) => boolean;
  /**
   * Call the facilitator's verify before settle (default `true`). When
   * `false`, the verify lifecycle and its hooks are skipped entirely and
   * settle is the only facilitator call.
   */
  verifyBeforeSettle?: boolean;
}

/**
 * Parse a price string (e.g., '$0.01' or '0.01') to atomic units.
 */
export function parsePrice(price: string, decimals = 6): string {
  const match = /^\$?(\d*)(?:\.(\d*))?$/.exec(price.trim());
  const [, whole = '', fraction = ''] = match ?? [];
  if (!match || (whole === '' && fraction === '')) {
    throw new Error(`Invalid price: ${price}`);
  }
  if (/[1-9]/.test(fraction.slice(decimals))) {
    throw new Error(`Invalid price: ${price} has more than ${decimals} decimals`);
  }
  const atomic = BigInt(
    `${whole || '0'}${fraction.slice(0, decimals).padEnd(decimals, '0')}`,
  );
  if (atomic === BigInt(0)) {
    throw new Error(`Invalid price: ${price}`);
  }
  return atomic.toString();
}

function encodePaymentResponse(body: Record<string, unknown>): string {
  return Buffer.from(JSON.stringify(body)).toString('base64');
}

/**
 * Decode a `Payment-Signature` header. Invalid base64, non-JSON, and
 * non-object payloads are rejected so the route answers 400 instead of 500.
 */
function decodePaymentHeader(
  header: string,
): { ok: true; payload: Record<string, unknown> } | { ok: false } {
  try {
    const parsed: unknown = JSON.parse(Buffer.from(header, 'base64').toString('utf-8'));
    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
      return { ok: false };
    }
    return { ok: true, payload: parsed as Record<string, unknown> };
  } catch {
    return { ok: false };
  }
}

/**
 * Prefer a facilitator HTTP status (e.g. 429) over a generic 500 when the
 * thrown error carries one. Out-of-range values stay 500.
 */
function httpStatusFromError(error: unknown): number {
  if (
    typeof error === 'object' &&
    error !== null &&
    'status' in error &&
    typeof (error as { status: unknown }).status === 'number'
  ) {
    const status = (error as { status: number }).status;
    if (Number.isInteger(status) && status >= 400 && status <= 599) {
      return status;
    }
  }
  return 500;
}

/**
 * Build a `ProtectedRequestContext` from the raw IncomingMessage.
 */
function buildProtectedRequestContext(req: PaymentRequest): ProtectedRequestContext {
  const url = req.url ?? '/';
  const path = url.split(/[?#]/)[0];
  return {
    method: (req.method ?? 'GET').toUpperCase(),
    path,
    url,
    getHeader: (name: string) => {
      const v = req.headers[name.toLowerCase()];
      if (Array.isArray(v)) return v[0];
      return v as string | undefined;
    },
  };
}

/**
 * Creates facilitator-agnostic Express middleware using the supplied client,
 * payment-requirements builder and match rule.
 */
export function createPaymentMiddleware<TKind extends { network: string }>(
  options: PaymentMiddlewareOptions<TKind>,
): GenericPaymentMiddleware {
  const { component, facilitator, description, buildRequirements } = options;
  const matchesAccepted = options.matchesAccepted ?? isOnAcceptedNetwork;
  const verifyBeforeSettle = options.verifyBeforeSettle ?? true;

  function warnIfVerifySkipped(hookName: string): void {
    if (!verifyBeforeSettle) {
      console.warn(
        `[x402] ${component} ${hookName} hook will never run: verifyBeforeSettle is false`,
      );
    }
  }

  const configuredNetworks = options.networks
    ? Array.isArray(options.networks)
      ? options.networks
      : [options.networks]
    : null; // null means "all networks"

  let cachedSupportedKinds: TKind[] | null = null;

  async function getAcceptedKinds(): Promise<TKind[]> {
    if (!cachedSupportedKinds) {
      const supported = await facilitator.getSupported();
      cachedSupportedKinds = supported.kinds;
    }
    if (configuredNetworks) {
      return cachedSupportedKinds.filter((k) => configuredNetworks.includes(k.network));
    }
    return cachedSupportedKinds;
  }

  /**
   * Create payment requirements for all accepted networks.
   */
  async function createAllPaymentRequirements(
    price: TokenPrice,
  ): Promise<PaymentRequirements[]> {
    return buildRequirements(await getAcceptedKinds(), price);
  }

  /**
   * Create the payment requirement that the buyer accepted, as
   * `matchesAccepted` selects it.
   */
  async function createPaymentRequirements(
    price: TokenPrice,
    accepted: PaymentRequirements,
  ): Promise<PaymentRequirements | null> {
    const all = await createAllPaymentRequirements(price);
    return all.find((r) => matchesAccepted(r, accepted)) ?? null;
  }

  // ==========================================================================
  // Hook registries
  // ==========================================================================

  const protectedRequestHooks: ProtectedRequestHook[] = [];
  const beforeVerifyHooks: BeforeVerifyHook[] = [];
  const afterVerifyHooks: AfterVerifyHook[] = [];
  const onVerifyFailureHooks: OnVerifyFailureHook[] = [];
  const beforeSettleHooks: BeforeSettleHook[] = [];
  const afterSettleHooks: AfterSettleHook[] = [];
  const onSettleFailureHooks: OnSettleFailureHook[] = [];
  const onVerifiedPaymentCanceledHooks: OnVerifiedPaymentCanceledHook[] = [];

  // Run after-verify hooks. Returns a `skipHandler` directive if any hook
  // requested the resource handler be bypassed.
  async function runAfterVerifyHooks(
    context: VerifyContext,
    verifyResult: HookVerifyResponse,
  ): Promise<{ contentType?: string; body?: unknown } | undefined> {
    const resultContext: VerifyResultContext = { ...context, result: verifyResult };
    let skipHandler: { contentType?: string; body?: unknown } | undefined;
    for (const [index, hook] of afterVerifyHooks.entries()) {
      try {
        const directive = await hook(resultContext);
        if (directive && 'skipHandler' in directive && directive.skipHandler) {
          skipHandler = directive.response ?? {};
        }
      } catch (err) {
        warnHookFailure(component, 'afterVerify', `manual hook #${index}`, err);
      }
    }
    return skipHandler;
  }

  // Run a verify lifecycle (beforeVerify → facilitator.verify → afterVerify
  // | onVerifyFailure). Returns either a verify response (with optional
  // `skipHandler` directive) or an `aborted` marker.
  async function runVerifyLifecycle(
    paymentPayload: { x402Version: number; payload: Record<string, unknown> },
    requirements: PaymentRequirements,
  ): Promise<
    | {
        kind: 'verified';
        result: HookVerifyResponse;
        skipHandler?: { contentType?: string; body?: unknown };
      }
    | { kind: 'aborted'; reason: string; message?: string }
    | { kind: 'failed'; result: HookVerifyResponse }
    | { kind: 'thrown'; error: Error }
  > {
    const context: VerifyContext = {
      paymentPayload,
      requirements,
    };

    for (const [index, hook] of beforeVerifyHooks.entries()) {
      try {
        const result = await hook(context);
        if (result && 'abort' in result && result.abort) {
          return { kind: 'aborted', reason: result.reason, message: result.message };
        }
        if (result && 'skip' in result && result.skip) {
          const skipHandler = await runAfterVerifyHooks(context, result.result);
          return { kind: 'verified', result: result.result, skipHandler };
        }
      } catch (err) {
        warnHookFailure(component, 'beforeVerify', `manual hook #${index}`, err);
      }
    }

    try {
      const verifyResult = await facilitator.verify(paymentPayload, requirements);

      if (!verifyResult.isValid) {
        // failed verify — run onVerifyFailure
        const failureContext: VerifyFailureContext = {
          ...context,
          error: new Error(verifyResult.invalidReason || 'Verification failed'),
        };
        for (const hook of onVerifyFailureHooks) {
          try {
            const recovery = await hook(failureContext);
            if (recovery && 'recovered' in recovery && recovery.recovered) {
              const skipHandler = await runAfterVerifyHooks(context, recovery.result);
              return { kind: 'verified', result: recovery.result, skipHandler };
            }
          } catch (err) {
            warnHookFailure(component, 'onVerifyFailure', 'manual hook', err);
          }
        }
        return { kind: 'failed', result: verifyResult };
      }

      const skipHandler = await runAfterVerifyHooks(context, verifyResult);
      return { kind: 'verified', result: verifyResult, skipHandler };
    } catch (error) {
      const failureContext: VerifyFailureContext = {
        ...context,
        error: error as Error,
      };
      for (const hook of onVerifyFailureHooks) {
        try {
          const recovery = await hook(failureContext);
          if (recovery && 'recovered' in recovery && recovery.recovered) {
            const skipHandler = await runAfterVerifyHooks(context, recovery.result);
            return { kind: 'verified', result: recovery.result, skipHandler };
          }
        } catch (err) {
          warnHookFailure(component, 'onVerifyFailure', 'manual hook', err);
        }
      }
      return { kind: 'thrown', error: error as Error };
    }
  }

  // Run a settle lifecycle (beforeSettle → facilitator.settle → afterSettle
  // | onSettleFailure). Returns either a settle response or a control-flow
  // directive equivalent to the standard SDK's behavior.
  async function runSettleLifecycle(
    paymentPayload: { x402Version: number; payload: Record<string, unknown> },
    requirements: PaymentRequirements,
  ): Promise<
    | { kind: 'settled'; result: HookSettleResponse }
    | { kind: 'aborted'; reason: string; message?: string }
    | { kind: 'thrown'; error: Error }
  > {
    const context: SettleContext = {
      paymentPayload,
      requirements,
    };

    for (const [index, hook] of beforeSettleHooks.entries()) {
      try {
        const result = await hook(context);
        if (result && 'abort' in result && result.abort) {
          return { kind: 'aborted', reason: result.reason, message: result.message };
        }
        if (result && 'skip' in result && result.skip) {
          const skipResultContext: SettleResultContext = {
            ...context,
            result: result.result,
          };
          for (const [idx, after] of afterSettleHooks.entries()) {
            try {
              await after(skipResultContext);
            } catch (err) {
              warnHookFailure(component, 'afterSettle', `manual hook #${idx}`, err);
            }
          }
          return { kind: 'settled', result: result.result };
        }
      } catch (err) {
        warnHookFailure(component, 'beforeSettle', `manual hook #${index}`, err);
      }
    }

    try {
      const settleResult = await facilitator.settle(paymentPayload, requirements);
      const resultContext: SettleResultContext = { ...context, result: settleResult };

      for (const [index, hook] of afterSettleHooks.entries()) {
        try {
          await hook(resultContext);
        } catch (err) {
          warnHookFailure(component, 'afterSettle', `manual hook #${index}`, err);
        }
      }

      return { kind: 'settled', result: settleResult };
    } catch (error) {
      const failureContext: SettleFailureContext = {
        ...context,
        error: error as Error,
      };
      for (const hook of onSettleFailureHooks) {
        try {
          const recovery = await hook(failureContext);
          if (recovery && 'recovered' in recovery && recovery.recovered) {
            return { kind: 'settled', result: recovery.result };
          }
        } catch (err) {
          warnHookFailure(component, 'onSettleFailure', 'manual hook', err);
        }
      }
      return { kind: 'thrown', error: error as Error };
    }
  }

  // Notify `onVerifiedPaymentCanceled` hooks that a verified payment never
  // reached settlement (e.g. because the protected handler threw, or
  // settlement itself failed in a non-recoverable way).
  async function dispatchVerifiedPaymentCanceled(
    paymentPayload: { x402Version: number; payload: Record<string, unknown> },
    requirements: PaymentRequirements,
    options: {
      reason: VerifiedPaymentCancellationReason;
      error?: unknown;
      responseStatus?: number;
    },
  ): Promise<void> {
    const context: VerifiedPaymentCanceledContext = {
      paymentPayload,
      requirements,
      reason: options.reason,
      error: options.error,
      responseStatus: options.responseStatus,
    };
    for (const [index, hook] of onVerifiedPaymentCanceledHooks.entries()) {
      try {
        await hook(context);
      } catch (err) {
        warnHookFailure(
          component,
          'onVerifiedPaymentCanceled',
          `manual hook #${index}`,
          err,
        );
      }
    }
  }

  // ==========================================================================
  // Middleware
  // ==========================================================================

  const api: GenericPaymentMiddleware = {
    require: (price: RoutePrice): MiddlewareFunction => {
      const tokenPrice = toTokenPrice(price);
      const routeConfig: ProtectedRouteConfig = { price };
      return async (req, res, next) => {
        try {
          // ----- onProtectedRequest --------------------------------------
          const requestContext = buildProtectedRequestContext(req);
          for (const [index, hook] of protectedRequestHooks.entries()) {
            try {
              const result = await hook(requestContext, routeConfig);
              if (result && 'grantAccess' in result && result.grantAccess) {
                next();
                return;
              }
              if (result && 'abort' in result && result.abort) {
                res.statusCode = 403;
                res.setHeader('Content-Type', 'application/json');
                res.end(JSON.stringify({ error: result.reason }));
                return;
              }
            } catch (err) {
              warnHookFailure(
                component,
                'onProtectedRequest',
                `manual hook #${index}`,
                err,
              );
            }
          }

          // Check for payment header
          const paymentHeader = req.headers['payment-signature'] as string | undefined;

          if (!paymentHeader) {
            // Return 402 Payment Required with all accepted networks
            const allRequirements = await createAllPaymentRequirements(tokenPrice);
            const url = req.url ?? '/';
            const resourceDescription = description ?? 'Paid resource';

            if (allRequirements.length === 0) {
              res.statusCode = 503;
              res.setHeader('Content-Type', 'application/json');
              res.end(JSON.stringify({ error: 'No payment networks available' }));
              return;
            }

            const paymentRequired = {
              x402Version: 2, // Version 2 required by Gateway API
              resource: {
                url,
                description: resourceDescription,
                mimeType: 'application/json',
              },
              accepts: allRequirements,
            };

            // x402 v2: Payment required info goes in PAYMENT-REQUIRED header (base64-encoded)
            const paymentRequiredHeader = Buffer.from(
              JSON.stringify(paymentRequired),
            ).toString('base64');

            res.statusCode = 402;
            res.setHeader('PAYMENT-REQUIRED', paymentRequiredHeader);
            res.setHeader('Content-Type', 'application/json');
            res.end(JSON.stringify({}));
            return;
          }

          const decoded = decodePaymentHeader(paymentHeader);
          if (!decoded.ok) {
            res.statusCode = 400;
            res.setHeader('Content-Type', 'application/json');
            res.end(JSON.stringify({ error: 'Invalid payment header' }));
            return;
          }
          const paymentPayload = decoded.payload as {
            x402Version: number;
            payload: Record<string, unknown>;
            accepted?: PaymentRequirements;
          };
          const acceptedRequirements = paymentPayload.accepted;

          if (!acceptedRequirements?.network) {
            res.statusCode = 400;
            res.setHeader('Content-Type', 'application/json');
            res.end(
              JSON.stringify({ error: 'Missing accepted requirements in payment' }),
            );
            return;
          }

          // Create requirements for the option the buyer chose
          const requirements = await createPaymentRequirements(
            tokenPrice,
            acceptedRequirements,
          );

          if (!requirements) {
            res.statusCode = 400;
            res.setHeader('Content-Type', 'application/json');
            res.end(
              JSON.stringify({
                error: `No payment option matches the accepted requirements for network ${acceptedRequirements.network}`,
              }),
            );
            return;
          }

          // ----- verify lifecycle ----------------------------------------
          const verify = verifyBeforeSettle
            ? await runVerifyLifecycle(paymentPayload, requirements)
            : ({ kind: 'skipped' } as const);

          if (verify.kind === 'aborted') {
            res.statusCode = 402;
            res.setHeader('Content-Type', 'application/json');
            res.end(
              JSON.stringify({
                error: 'Payment verification aborted',
                reason: verify.reason,
                ...(verify.message ? { message: verify.message } : {}),
              }),
            );
            return;
          }

          if (verify.kind === 'failed') {
            res.statusCode = 402;
            res.setHeader('Content-Type', 'application/json');
            res.end(
              JSON.stringify({
                error: 'Payment verification failed',
                reason: verify.result.invalidReason,
              }),
            );
            return;
          }

          if (verify.kind === 'thrown') {
            throw verify.error;
          }

          const verifyResult = verify.kind === 'verified' ? verify.result : undefined;
          const skipHandlerDirective =
            verify.kind === 'verified' ? verify.skipHandler : undefined;

          // ----- settle lifecycle ----------------------------------------
          const settle = await runSettleLifecycle(paymentPayload, requirements);

          if (settle.kind === 'aborted') {
            await dispatchVerifiedPaymentCanceled(paymentPayload, requirements, {
              reason: 'handler_failed',
              responseStatus: 402,
            });
            res.statusCode = 402;
            res.setHeader('Content-Type', 'application/json');
            res.end(
              JSON.stringify({
                error: 'Payment settlement aborted',
                reason: settle.reason,
                ...(settle.message ? { message: settle.message } : {}),
              }),
            );
            return;
          }

          if (settle.kind === 'thrown') {
            await dispatchVerifiedPaymentCanceled(paymentPayload, requirements, {
              reason: 'handler_failed',
              error: settle.error,
              responseStatus: 402,
            });
            throw settle.error;
          }

          const settleResult = settle.result;

          if (!settleResult.success) {
            // Pending is not a cancellation: the payment is in flight and is reconciled via getStatus.
            const pending = settleResult.errorReason === FACILITATOR_SETTLEMENT_PENDING;
            if (!pending) {
              await dispatchVerifiedPaymentCanceled(paymentPayload, requirements, {
                reason: 'handler_failed',
                responseStatus: 402,
              });
            }
            const settlementStatus = (
              settleResult as { extensions?: Record<string, unknown> }
            ).extensions?.['settlement-status'];
            res.statusCode = 402;
            res.setHeader('Content-Type', 'application/json');
            res.setHeader(
              'PAYMENT-RESPONSE',
              encodePaymentResponse({
                success: false,
                errorReason: settleResult.errorReason,
                network: requirements.network,
                ...(settlementStatus
                  ? { extensions: { 'settlement-status': settlementStatus } }
                  : {}),
              }),
            );
            res.end(
              JSON.stringify({
                error: pending
                  ? 'Payment settlement pending'
                  : 'Payment settlement failed',
                reason: settleResult.errorReason,
                ...(settlementStatus ? { settlementStatus } : {}),
              }),
            );
            return;
          }

          // Attach payment info to request
          req.payment = {
            verified: true,
            payer: settleResult.payer ?? verifyResult?.payer ?? '',
            amount: requirements.amount,
            network: requirements.network,
            asset: requirements.asset,
            transaction: settleResult.transaction,
          };

          res.setHeader(
            'PAYMENT-RESPONSE',
            encodePaymentResponse({
              success: true,
              transaction: settleResult.transaction,
              network: requirements.network,
              payer: settleResult.payer ?? verifyResult?.payer ?? '',
            }),
          );

          // If a verify hook requested the protected handler be skipped, write
          // a 200 response now and bypass `next()`. Mirrors x402HTTPResourceServer's
          // processSkipHandlerSettlement.
          if (skipHandlerDirective) {
            const contentType = skipHandlerDirective.contentType ?? 'application/json';
            const body = skipHandlerDirective.body ?? {};
            res.statusCode = 200;
            res.setHeader('Content-Type', contentType);
            res.end(typeof body === 'string' ? body : JSON.stringify(body));
            return;
          }

          // Hand off to protected handler. If it throws synchronously, treat
          // it as a verified-payment-canceled scenario.
          try {
            await Promise.resolve(next());
          } catch (handlerError) {
            await dispatchVerifiedPaymentCanceled(paymentPayload, requirements, {
              reason: 'handler_threw',
              error: handlerError,
            });
            throw handlerError;
          }
        } catch (error) {
          res.statusCode = httpStatusFromError(error);
          res.setHeader('Content-Type', 'application/json');
          res.end(
            JSON.stringify({
              error: 'Payment processing error',
              message: (error as Error).message,
            }),
          );
        }
      };
    },

    verify: async (payment) => {
      try {
        const paymentPayload = payment as {
          paymentPayload: unknown;
          paymentRequirements: PaymentRequirements;
        };
        const result = await facilitator.verify(
          paymentPayload.paymentPayload as Parameters<typeof facilitator.verify>[0],
          paymentPayload.paymentRequirements,
        );
        return {
          valid: result.isValid,
          payer: result.payer,
          error: result.invalidReason,
        };
      } catch (error) {
        return {
          valid: false,
          error: (error as Error).message,
        };
      }
    },

    settle: async (payment) => {
      try {
        const paymentPayload = payment as {
          paymentPayload: unknown;
          paymentRequirements: PaymentRequirements;
        };
        const result = await facilitator.settle(
          paymentPayload.paymentPayload as Parameters<typeof facilitator.settle>[0],
          paymentPayload.paymentRequirements,
        );
        const { extensions } = result as { extensions?: Record<string, unknown> };
        return {
          success: result.success,
          transaction: result.transaction,
          error: result.errorReason,
          ...(extensions ? { extensions } : {}),
        };
      } catch (error) {
        return {
          success: false,
          error: (error as Error).message,
        };
      }
    },

    onProtectedRequest: (hook) => {
      protectedRequestHooks.push(hook);
      return api;
    },
    onBeforeVerify: (hook) => {
      warnIfVerifySkipped('onBeforeVerify');
      beforeVerifyHooks.push(hook);
      return api;
    },
    onAfterVerify: (hook) => {
      warnIfVerifySkipped('onAfterVerify');
      afterVerifyHooks.push(hook);
      return api;
    },
    onVerifyFailure: (hook) => {
      warnIfVerifySkipped('onVerifyFailure');
      onVerifyFailureHooks.push(hook);
      return api;
    },
    onBeforeSettle: (hook) => {
      beforeSettleHooks.push(hook);
      return api;
    },
    onAfterSettle: (hook) => {
      afterSettleHooks.push(hook);
      return api;
    },
    onSettleFailure: (hook) => {
      onSettleFailureHooks.push(hook);
      return api;
    },
    onVerifiedPaymentCanceled: (hook) => {
      onVerifiedPaymentCanceledHooks.push(hook);
      return api;
    },
  };

  return api;
}

function isOnAcceptedNetwork(
  requirement: PaymentRequirements,
  accepted: PaymentRequirements,
): boolean {
  return requirement.network === accepted.network;
}

/**
 * The token price of a route price. A string price is a USDC price.
 *
 * @throws When a price in a token other than USDC starts with `$`
 */
function toTokenPrice(price: RoutePrice): TokenPrice {
  if (typeof price === 'string') {
    return { token: 'USDC', price };
  }
  if (price.token === 'USDC') {
    return price;
  }
  if (price.price.trim().startsWith('$')) {
    throw new Error(
      `Invalid price: ${price.price} for ${price.token}. $ is a USDC price`,
    );
  }
  return price;
}
