import { ExactEvmScheme } from '@x402/evm/exact/server';
import type { AssetAmount, Network, PaymentRequirements, Price } from '@x402/core/types';
import { getTokenConfig } from '../config';
import { GATEWAY_AUTH_VALIDITY_WINDOW_SECONDS } from '../constants';
import { isBatchPayment } from '../detection';
import { parsePrice as parseTokenAmount } from './middleware';
import {
  acceptedBatchingVersions,
  type GatewayAsset,
  type GatewaySupportedKind,
} from './gateway';

/**
 * Gateway EVM Scheme for x402 resource servers.
 *
 * Extends `ExactEvmScheme` with three Gateway-specific behaviors:
 *
 * 1. **enhancePaymentRequirements** — merges `supportedKind.extra` (e.g.
 *    `verifyingContract`) into `paymentRequirements.extra`. The base
 *    `ExactEvmScheme` discards this, but Gateway clients need it to
 *    construct the correct EIP-712 signing domain. It sets `extra.version`
 *    to a batching version Gateway accepts for the requirement's asset.
 *
 * 2. **String prices** — `parsePrice()` reads a string price, for example
 *    `'$0.01'`, as USDC, with the USDC address and decimals from
 *    `CHAIN_CONFIGS`.
 *
 * 3. **Money parsers** — registers USDC address mappings for all
 *    Gateway-supported networks so a number price works without manual
 *    `registerMoneyParser()` calls.
 *
 * @example
 * ```typescript
 * import { GatewayEvmScheme } from "@circle-fin/x402-batching/server";
 * import { x402ResourceServer } from "@x402/express";
 *
 * const resourceServer = new x402ResourceServer(facilitators)
 *   .register("eip155:5042002", new GatewayEvmScheme());
 * ```
 */
export class GatewayEvmScheme extends ExactEvmScheme {
  constructor() {
    super();
    this.registerGatewayMoneyParsers();
  }

  /**
   * Enhances payment requirements by merging the facilitator's extra data.
   *
   * The base `ExactEvmScheme.enhancePaymentRequirements` returns requirements
   * unchanged, dropping `supportedKind.extra`. Gateway payments require
   * `extra.verifyingContract` (and other fields like `name`, `version`) to
   * be present for clients to construct the correct signing domain.
   *
   * Gateway publishes one kind for each network, with one `extra.version`,
   * and lists the batching versions it accepts for each asset in
   * `extra.assets[].authorizationVersions`. The requirement gets the lowest
   * version that Gateway accepts for its asset, so buyers on older SDK
   * releases can pay.
   *
   * @throws When Gateway does not list the requirement's asset for the network
   */
  async enhancePaymentRequirements(
    paymentRequirements: PaymentRequirements,
    supportedKind: {
      x402Version: number;
      scheme: string;
      network: Network;
      extra?: Record<string, unknown>;
    },
    extensionKeys: string[],
  ): Promise<PaymentRequirements> {
    void extensionKeys;
    return {
      ...paymentRequirements,
      maxTimeoutSeconds: Math.max(
        paymentRequirements.maxTimeoutSeconds,
        GATEWAY_AUTH_VALIDITY_WINDOW_SECONDS,
      ),
      extra: mergeExtra(paymentRequirements, supportedKind),
    };
  }

  /**
   * Parses a route price. A string price is in USDC, for example `'$0.01'`,
   * with the address and decimals from `CHAIN_CONFIGS`. A number and an
   * `AssetAmount` go to `ExactEvmScheme.parsePrice`.
   *
   * @throws When the network does not have USDC in `CHAIN_CONFIGS`, or a string
   * price is not a number in the USDC decimals
   */
  async parsePrice(price: Price, network: Network): Promise<AssetAmount> {
    if (typeof price !== 'string') {
      return super.parsePrice(price, network);
    }
    const usdc = getTokenConfig(network, 'USDC');
    if (!usdc) {
      throw new Error(`USDC is not available on ${network}`);
    }
    return { asset: usdc.address, amount: parseTokenAmount(price, usdc.decimals) };
  }

  /**
   * Registers money parsers for all Gateway-supported networks.
   *
   * Registers a single parser that converts a number price to USDC atomic
   * units for any Gateway-supported chain, with the USDC address and decimals
   * from `CHAIN_CONFIGS`.
   *
   * Returns `null` for unknown networks so `ExactEvmScheme`'s built-in
   * parser handles them.
   */
  private registerGatewayMoneyParsers(): void {
    this.registerMoneyParser(async (amount: number, network: Network) => {
      const usdc = getTokenConfig(network, 'USDC');
      if (!usdc) {
        return null; // Not a Gateway network — let default parser handle it
      }
      return {
        amount: Math.round(amount * 10 ** usdc.decimals).toString(),
        asset: usdc.address,
      };
    });
  }
}

function mergeExtra(
  paymentRequirements: PaymentRequirements,
  kind: GatewaySupportedKind,
): Record<string, unknown> {
  const extra = { ...paymentRequirements.extra, ...kind.extra };
  if (!isBatchPayment(kind)) {
    return extra;
  }

  const asset = getGatewayAsset(kind, paymentRequirements.asset);
  if (!asset) {
    throw new Error(
      `Gateway does not accept asset ${paymentRequirements.asset} for batching on ${kind.network}`,
    );
  }
  const [version] = acceptedBatchingVersions(kind, asset);
  return { ...extra, version };
}

/**
 * The asset that a kind lists at an address, or `undefined` when the kind does
 * not list the address. The address match ignores case.
 */
function getGatewayAsset(
  kind: GatewaySupportedKind,
  address: string,
): GatewayAsset | undefined {
  return kind.extra?.assets?.find(
    (candidate) => candidate.address.toLowerCase() === address.toLowerCase(),
  );
}
