/**
 * Supported chain names type.
 */
export type SupportedChainName = keyof typeof GATEWAY_DOMAINS;

/**
 * A token that Gateway holds balances in.
 */
export type TokenName = 'USDC' | 'EURC' | 'cirBTC';

/**
 * The contract address and decimals of a token on one chain.
 */
export interface TokenConfig {
  address: Address;
  decimals: number;
}

/**
 * Chain configuration with contract addresses.
 */
export interface ChainConfig {
  chain: Chain;
  domain: number;
  tokens: Partial<Record<TokenName, TokenConfig>>;
  gatewayWallet: Address;
  gatewayMinter: Address;
  rpcUrl?: string;
}

