const TOKENS_BY_NETWORK = new Map(
  Object.values(CHAIN_CONFIGS).map(({ chain, tokens }) => [`eip155:${chain.id}`, tokens]),
);

export function isUsdc(requirement: { network: string; asset: string }): boolean {
  return isToken(requirement, 'USDC');
}

/**
 * Whether the asset of a requirement is the address of a token in
 * `CHAIN_CONFIGS` for the requirement's network. The address match ignores case.
 */
export function isToken(
  requirement: { network: string; asset: string },
  token: TokenName,
): boolean {
  return (
    getTokenConfig(requirement.network, token)?.address.toLowerCase() ===
    requirement.asset?.toLowerCase()
  );
}

/**
 * The address and decimals of a token on a CAIP-2 network, or `undefined` when
 * `CHAIN_CONFIGS` has no such token on that network.
 */
export function getTokenConfig(
  network: string,
  token: TokenName,
): TokenConfig | undefined {
  return TOKENS_BY_NETWORK.get(network)?.[token];
}
